insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('28504cda-ba31-4165-b584-8ccd8d6d1eef', 'N4', '数量詞＋も〜', 'Những/ Tận ~ (nhấn mạnh số lượng nhiều/lâu hơn dự kiến)', 'も sau số lượng nhấn mạnh mức độ nhiều/lâu hơn mong đợi', '[Số lượng] + も + ~', 'Nhấn mạnh số lượng/thời gian nhiều, lâu hơn mong đợi', NULL, NULL, NULL, '{}', NULL, 44, '数量詞＋も〜', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('cf26310a-21ab-405e-bdf4-fd46616117e6', 'N4', 'Vます／Aい／Aな＋すぎます', 'Quá nhiều...', 'すぎる gắn sau thân động từ/tính từ để diễn tả mức độ vượt quá bình thường', 'V(ます形bỏます)／Aい(bỏい)／Aな(bỏな) + すぎます', 'Diễn tả một hành động/tính chất ở mức độ quá nhiều, quá mức', NULL, NULL, NULL, '{}', NULL, 44, 'Vます／Aい／Aな＋すぎます', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('d4f5253e-be53-4e86-b213-6102484b632a', 'N4', 'Aい（く）／Aな（に）＋V', 'Tính từ bổ nghĩa cho động từ (thể phó từ hóa)', 'い形容詞 đổi い→く, な形容詞 thêm に, trước khi bổ nghĩa cho động từ', 'Aい → Aく + V ／ Aな → Aに + V', 'Chuyển tính từ thành phó từ để bổ nghĩa cho động từ đứng sau', NULL, NULL, NULL, '{}', NULL, 44, 'Aい（く）／Aな（に）＋V', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('455b24fe-80fd-4b94-b3c4-9b0c038a4bb1', 'N4', 'Nにします', 'Biểu thị sự lựa chọn hoặc quyết định', 'にする dùng để chọn/quyết định một thứ trong nhiều lựa chọn', 'N + にします', 'Diễn tả việc chọn hoặc quyết định một thứ gì đó', NULL, NULL, NULL, '{}', NULL, 44, 'Nにします', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('f9fb3b07-760b-44b4-8fe7-5eb7a7b9132e', 'N4', 'Vる／Vた／Vない／Aい／Aな／Nの＋場合', 'Trong trường hợp ~, khi ~', '場合 nêu một tình huống/điều kiện giả định, trang trọng hơn たら/なら', 'V(thể thường)／Aい／Aな(な)／N(の) + 場合、〜', 'Nêu một trường hợp/tình huống giả định và kết quả/cách xử lý tương ứng', NULL, NULL, NULL, '{}', NULL, 44, 'Vる／Vた／Vない／Aい／Aな／Nの＋場合', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('d9ef7436-7bbb-4676-846f-7df299a1c4c1', 'N4', 'V（普通形）／Aい／Aな／Nな＋のに', 'Thế mà, vậy mà (nghịch với điều mong đợi)', 'のに ở đây khác với のに mục đích (Vるのに使う) — đây là のに nghịch, biểu thị bất ngờ/bất mãn', 'V(thể thường)／Aい／Aな(な)／N(な) + のに、〜', 'Diễn tả sự trái ngược, bất ngờ hoặc bất mãn giữa 2 vế câu', NULL, NULL, NULL, '{}', NULL, 44, 'V（普通形）／Aい／Aな／Nな＋のに', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('06566380-163a-42ef-b882-da4a59fd478c', 'N4', 'Vた＋ばかりです', 'Vừa mới làm gì ~', 'ばかり nhấn mạnh việc vừa mới xảy ra, khoảng cách thời gian rất ngắn', 'V(た形) + ばかりです', 'Diễn tả một hành động vừa mới hoàn thành xong', NULL, NULL, NULL, '{}', NULL, 44, 'Vた＋ばかりです', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('e74ac172-f2e4-46cf-a2f9-fd24a18cf6a3', 'N4', 'Vます／Aい／Aな＋そうです', 'Suy đoán bằng mắt: sắp xảy ra / trông có vẻ ~', 'そうです dùng mắt để suy đoán, khác với そうです nghe nói (V/A普通形+そうです)', 'V(ます形bỏます)／Aい(bỏい)／Aな(bỏな) + そうです', NULL, NULL, NULL, NULL, '{}', NULL, 44, 'Vます／Aい／Aな＋そうです', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('6dc03016-0c3b-4d72-9fde-8d26eb8de0f5', 'N4', 'Vて来ます', 'Đi làm gì đó rồi quay về / Đã dần trở nên ~', 'て来る sau động từ di chuyển/hành động = đi làm rồi về; sau động từ biến đổi = dần trở nên', 'V(て形) + 来ます', NULL, NULL, NULL, NULL, '{}', NULL, 44, 'Vて来ます', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('dbe369ec-79fb-495f-8da2-2a19d65cd2bc', 'N4', 'Vます＋やすいです／にくいです', 'Dễ làm việc gì / Khó làm việc gì', 'やすい (dễ) và にくい (khó) là 2 nét nghĩa đối lập của cùng 1 mẫu', 'V(ます形 bỏ ます) + やすいです／にくいです', NULL, NULL, NULL, NULL, '{}', NULL, 44, 'Vます＋やすいです／にくいです', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('72c693cc-992d-4132-9f88-4f11dcd44576', 'N4', 'Vる／Vている／Vた＋ところです', 'Chuẩn bị làm ~ / Đang làm ~ / Vừa làm ~', 'ところ chỉ 1 thời điểm cụ thể trong tiến trình hành động: trước khi làm／đang làm／ngay sau khi làm xong', 'Vる／Vている／Vた + ところです', NULL, NULL, NULL, NULL, '{}', NULL, 44, 'Vる／Vている／Vた＋ところです', 'pdf', 'ok')
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('8ba8f78c-164a-4e0a-bdf4-fa2a4d20dfe6', 'e74ac172-f2e4-46cf-a2f9-fd24a18cf6a3', 1, '(Có vẻ) Sắp ~ đến nơi rồi (dựa trên Vます)', 'V(ます形 bỏ ます) + そうです', NULL, NULL, 44, 'pdf');
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('a43e9d48-863c-46b4-991a-67725c91ec54', 'e74ac172-f2e4-46cf-a2f9-fd24a18cf6a3', 2, 'Trông có vẻ ~ (suy đoán qua bề ngoài của sự vật, dựa trên Aい/Aな)', 'Aい(bỏい)／Aな(bỏな) + そうです', NULL, NULL, 44, 'pdf');
