insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('df282590-57e0-4d98-a589-cf403a735fe6', '6dc03016-0c3b-4d72-9fde-8d26eb8de0f5', 2, 'Đã (trở nên) ~ rồi (biến đổi dần dần)', 'V(て形) + きます／きた', NULL, NULL, 44, 'pdf');
